// Minimal reimplementation of Python's eval() for literal expressions:
// lists, tuples, numbers (int/float), strings, True/False/None, unary +/-.

import { PyFloat } from './pytypes.mjs';

class Parser {
  constructor(src) {
    this.src = src;
    this.pos = 0;
  }

  error(msg) {
    throw new SyntaxError(msg);
  }

  skipWs() {
    while (this.pos < this.src.length && /\s/.test(this.src[this.pos])) this.pos++;
  }

  atEnd() {
    return this.pos >= this.src.length;
  }

  peek() {
    return this.src[this.pos];
  }

  parseValue() {
    this.skipWs();
    if (this.atEnd()) this.error('unexpected EOF while parsing');
    const ch = this.peek();
    if (ch === '[') return this.parseSeq('[', ']');
    if (ch === '(') return this.parseSeq('(', ')');
    if (ch === "'" || ch === '"') return this.parseString();
    if (ch === '-' || ch === '+') {
      this.pos++;
      return this.applyUnary(ch, this.parseValue());
    }
    if (/[0-9.]/.test(ch)) return this.parseNumber();
    if (/[A-Za-z_]/.test(ch)) {
      const name = this.parseName();
      if (name === 'True') return true;
      if (name === 'False') return false;
      if (name === 'None') return null;
      this.error(`invalid syntax near '${name}'`);
    }
    this.error(`unexpected character '${ch}'`);
  }

  parseSeq(open, close) {
    this.pos++; // consume open
    const items = [];
    this.skipWs();
    if (this.peek() === close) {
      this.pos++;
      return items;
    }
    for (;;) {
      items.push(this.parseValue());
      this.skipWs();
      if (this.atEnd()) this.error(`'${open}' was never closed`);
      const ch = this.peek();
      if (ch === ',') {
        this.pos++;
        this.skipWs();
        if (this.peek() === close) {
          this.pos++; // trailing comma
          return items;
        }
        continue;
      }
      if (ch === close) {
        this.pos++;
        return items;
      }
      this.error(`expected ',' or '${close}'`);
    }
  }

  parseNumber() {
    const re = /(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?/y;
    re.lastIndex = this.pos;
    const m = re.exec(this.src);
    if (!m) this.error('invalid numeric literal');
    this.pos += m[0].length;
    const text = m[0];
    if (/[.eE]/.test(text)) return new PyFloat(Number(text));
    return BigInt(text);
  }

  parseString() {
    const quote = this.src[this.pos++];
    let out = '';
    for (;;) {
      if (this.atEnd()) this.error('unterminated string literal');
      const ch = this.src[this.pos++];
      if (ch === quote) return out;
      if (ch !== '\\') {
        out += ch;
        continue;
      }
      if (this.atEnd()) this.error('unterminated string literal');
      const esc = this.src[this.pos++];
      switch (esc) {
        case 'n': out += '\n'; break;
        case 't': out += '\t'; break;
        case 'r': out += '\r'; break;
        case 'a': out += '\x07'; break;
        case 'b': out += '\b'; break;
        case 'f': out += '\f'; break;
        case 'v': out += '\v'; break;
        case '0': out += '\0'; break;
        case '\\': out += '\\'; break;
        case "'": out += "'"; break;
        case '"': out += '"'; break;
        case 'x': {
          const hex = this.src.slice(this.pos, this.pos + 2);
          if (!/^[0-9a-fA-F]{2}$/.test(hex)) this.error('invalid \\x escape');
          out += String.fromCharCode(parseInt(hex, 16));
          this.pos += 2;
          break;
        }
        case 'u': {
          const hex = this.src.slice(this.pos, this.pos + 4);
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) this.error('invalid \\u escape');
          out += String.fromCharCode(parseInt(hex, 16));
          this.pos += 4;
          break;
        }
        default:
          out += `\\${esc}`; // Python keeps unknown escapes verbatim
      }
    }
  }

  parseName() {
    const re = /[A-Za-z_][A-Za-z0-9_]*/y;
    re.lastIndex = this.pos;
    const m = re.exec(this.src);
    this.pos += m[0].length;
    return m[0];
  }

  applyUnary(op, v) {
    const sign = op === '-' ? -1 : 1;
    if (typeof v === 'bigint') return sign === -1 ? -v : v;
    if (v instanceof PyFloat) return new PyFloat(sign * v.value);
    if (v === true) return BigInt(sign);
    if (v === false) return 0n;
    this.error(`bad operand type for unary '${op}'`);
  }
}

export function pyEval(src) {
  const p = new Parser(src);
  const value = p.parseValue();
  p.skipWs();
  if (!p.atEnd()) p.error(`unexpected trailing characters at position ${p.pos}`);
  return value;
}

