// Reimplementation of the boltons.iterutils helpers used by the script.
// Arrays stand in for Python lists/tuples; strings and scalars are atomic.

export function* flatten(iterable) {
  for (const item of iterable) {
    if (Array.isArray(item)) {
      yield* flatten(item);
    } else {
      yield item;
    }
  }
}

export function* chunked(iterable, chunkSize) {
  if (!Number.isInteger(chunkSize) || chunkSize < 1) {
    throw new TypeError('chunk_size expected a positive integer');
  }
  const items = Array.isArray(iterable) ? iterable : Array.from(iterable);
  for (let i = 0; i < items.length; i += chunkSize) {
    yield items.slice(i, i + chunkSize);
  }
}

